DO $$
DECLARE owner uuid; a public.categories; b public.categories; hist public.categories; sys public.categories;
  bank public.accounts; bank2 public.accounts; loan1 public.loans; loan2 public.loans; asset1 public.non_cash_assets; asset2 public.non_cash_assets;
  goal public.goals; r jsonb; cmd jsonb; op uuid:=gen_random_uuid(); avail numeric; rev uuid; all_records jsonb;
BEGIN
 SELECT owner_id INTO owner FROM public.budget_accounts WHERE id=27;
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=owner AND email LIKE '%@example.invalid') THEN RAISE EXCEPTION 'Expected preview budget'; END IF;
 PERFORM set_config('request.jwt.claim.sub',owner::text,true);
 INSERT INTO public.categories(user_id,account_id,name,monthly_amount) VALUES(owner,27,'Rollback tidy A',20) RETURNING * INTO a;
 INSERT INTO public.categories(user_id,account_id,name,monthly_amount) VALUES(owner,27,'Rollback tidy B',30) RETURNING * INTO b;
 INSERT INTO public.categories(user_id,account_id,name,monthly_amount) VALUES(owner,27,'Rollback history',10) RETURNING * INTO hist;
 INSERT INTO public.categories(user_id,account_id,name,is_system) VALUES(owner,27,'Rollback system',true) RETURNING * INTO sys;
 SELECT public.budget_available_money(27) INTO avail;
 cmd:=jsonb_build_object('action','archive','records',jsonb_build_array(jsonb_build_object('id',a.id,'revision',a.revision),jsonb_build_object('id',b.id,'revision',b.revision)));
 r:=public.manage_envelopes(27,op,cmd);
 IF r->>'status'<>'saved' OR NOT(SELECT is_archived FROM public.categories WHERE id=a.id) OR NOT(SELECT is_archived FROM public.categories WHERE id=b.id) OR public.budget_available_money(27)<>avail THEN RAISE EXCEPTION 'Archive incorrect'; END IF;
 IF public.manage_envelopes(27,op,cmd)<>r THEN RAISE EXCEPTION 'Archive receipt replay failed'; END IF;
 IF public.manage_envelopes(27,gen_random_uuid(),cmd)->>'status'<>'conflict' THEN RAISE EXCEPTION 'Stale archive accepted'; END IF;
 SELECT * INTO a FROM public.categories WHERE id=a.id; SELECT * INTO b FROM public.categories WHERE id=b.id;
 r:=public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','restore','records',jsonb_build_array(jsonb_build_object('id',a.id,'revision',a.revision),jsonb_build_object('id',b.id,'revision',b.revision))));
 IF (SELECT is_archived FROM public.categories WHERE id=a.id) OR (SELECT monthly_amount FROM public.categories WHERE id=b.id)<>30 THEN RAISE EXCEPTION 'Restore lost target'; END IF;
 SELECT * INTO a FROM public.categories WHERE id=a.id; SELECT * INTO b FROM public.categories WHERE id=b.id;
 UPDATE public.categories SET current_balance=10 WHERE id=b.id RETURNING * INTO b;
 BEGIN
  PERFORM public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','archive','records',jsonb_build_array(jsonb_build_object('id',a.id,'revision',a.revision),jsonb_build_object('id',b.id,'revision',b.revision))));
  RAISE EXCEPTION 'Funded envelope archived';
 EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 IF (SELECT is_archived FROM public.categories WHERE id=a.id) THEN RAISE EXCEPTION 'Partial archive'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision) ORDER BY id DESC) INTO all_records FROM public.categories WHERE account_id=27 AND NOT is_system AND NOT coalesce(is_buffer,false) AND NOT coalesce(is_archived,false);
 r:=public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','order','records',all_records));
 IF r->>'status'<>'saved' OR (SELECT sort_order FROM public.categories WHERE id=(all_records->0->>'id')::bigint)<>0 THEN RAISE EXCEPTION 'Order failed'; END IF;
 SELECT * INTO a FROM public.categories WHERE id=a.id;
 IF public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','order','records',jsonb_build_array(jsonb_build_object('id',a.id,'revision',a.revision))))->>'status'<>'conflict' THEN RAISE EXCEPTION 'Incomplete order accepted'; END IF;
 -- Even a zero-balance envelope with funding/audit history cannot be removed.
 INSERT INTO public.category_monthly_funding(user_id,account_id,category_id,month,funded_amount) VALUES(owner,27,hist.id,'2026-11-01',100);
 SELECT * INTO hist FROM public.categories WHERE id=hist.id;
 BEGIN
  PERFORM public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','delete','records',jsonb_build_array(jsonb_build_object('id',hist.id,'revision',hist.revision))));
  RAISE EXCEPTION 'History lost';
 EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.envelope_housekeeping(27)) c WHERE (c->>'id')::bigint=hist.id AND jsonb_array_length(c->'usage')>0) THEN RAISE EXCEPTION 'History evidence absent'; END IF;
 cmd:=jsonb_build_object('action','delete','records',jsonb_build_array(jsonb_build_object('id',a.id,'revision',a.revision)));op:=gen_random_uuid();
 r:=public.manage_envelopes(27,op,cmd);
 IF EXISTS(SELECT 1 FROM public.categories WHERE id=a.id) OR public.manage_envelopes(27,op,cmd)<>r THEN RAISE EXCEPTION 'Unused removal/replay failed'; END IF;
 r:=public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','rename-system','records',jsonb_build_array(jsonb_build_object('id',sys.id,'revision',sys.revision)),'name','System renamed','notes','Synthetic note'));
 IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=sys.id AND is_system AND name='System renamed') THEN RAISE EXCEPTION 'System label changed behavior'; END IF;
 RAISE NOTICE 'PASS archive/restore, stale versions, atomic blocked batch, order completeness, history protection, deletion replay, system labels';
 -- Goal source changes: preserve all money/history; review only the dedicated-account exclusion.
 INSERT INTO public.accounts(user_id,account_id,name,balance,account_type,include_in_totals) VALUES(owner,27,'Rollback goal cash A',100,'savings',false) RETURNING * INTO bank;
 INSERT INTO public.accounts(user_id,account_id,name,balance,account_type,include_in_totals) VALUES(owner,27,'Rollback goal cash B',200,'savings',true) RETURNING * INTO bank2;
 INSERT INTO public.goals(user_id,account_id,name,target_amount,goal_type,purpose,linked_account_id) VALUES(owner,27,'Rollback cash goal',1000,'account-linked','reserve',bank.id) RETURNING * INTO goal;
 UPDATE public.accounts SET linked_goal_id=goal.id WHERE id=bank.id RETURNING * INTO bank;
 SELECT public.budget_available_money(27) INTO avail;
 cmd:=jsonb_build_object('action','relink','id',goal.id,'revision',goal.revision,'source',jsonb_build_object('table','accounts','id',bank2.id),'sourceRevisions',jsonb_build_object('accounts:'||bank.id,bank.revision,'accounts:'||bank2.id,bank2.revision));op:=gen_random_uuid();
 r:=public.manage_goal(27,op,cmd);
 IF public.budget_available_money(27)<>avail-200 OR (SELECT include_in_totals FROM public.accounts WHERE id=bank.id) OR (SELECT linked_goal_id FROM public.accounts WHERE id=bank.id) IS NOT NULL OR (SELECT balance FROM public.accounts WHERE id=bank2.id)<>200 THEN RAISE EXCEPTION 'Account source changed wrong money'; END IF;
 IF public.manage_goal(27,op,cmd)<>r OR public.manage_goal(27,gen_random_uuid(),cmd)->>'status'<>'conflict' THEN RAISE EXCEPTION 'Goal replay/stale failed'; END IF;
 SELECT * INTO goal FROM public.goals WHERE id=goal.id; SELECT * INTO bank2 FROM public.accounts WHERE id=bank2.id;
 cmd:=jsonb_build_object('action','delete','id',goal.id,'revision',goal.revision,'sourceRevisions',jsonb_build_object('accounts:'||bank2.id,bank2.revision));op:=gen_random_uuid();
 r:=public.manage_goal(27,op,cmd);
 IF public.budget_available_money(27)<>avail-200 OR EXISTS(SELECT 1 FROM public.goals WHERE id=goal.id) OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE id=bank2.id AND balance=200 AND NOT include_in_totals AND linked_goal_id IS NULL) OR public.manage_goal(27,op,cmd)<>r THEN RAISE EXCEPTION 'Goal deletion changed account inclusion/balance or replay failed'; END IF;
 SELECT * INTO b FROM public.categories WHERE id=b.id;
 INSERT INTO public.goals(user_id,account_id,name,target_amount,monthly_contribution,goal_type,purpose,linked_category_id) VALUES(owner,27,'Rollback envelope goal',1000,50,'envelope','purchase',b.id) RETURNING * INTO goal;
 UPDATE public.categories SET is_goal=true WHERE id=b.id RETURNING * INTO b;
 SELECT * INTO hist FROM public.categories WHERE id=hist.id;
 cmd:=jsonb_build_object('action','relink','id',goal.id,'revision',goal.revision,'source',jsonb_build_object('table','categories','id',hist.id),'sourceRevisions',jsonb_build_object('categories:'||b.id,b.revision,'categories:'||hist.id,hist.revision));
 SELECT public.budget_available_money(27) INTO avail;
 r:=public.manage_goal(27,gen_random_uuid(),cmd);
 IF public.budget_available_money(27)<>avail OR NOT EXISTS(SELECT 1 FROM public.categories WHERE id=b.id AND NOT is_goal AND current_balance=10 AND monthly_amount=30) OR NOT EXISTS(SELECT 1 FROM public.categories WHERE id=hist.id AND is_goal AND monthly_amount=50) THEN RAISE EXCEPTION 'Envelope source effect wrong'; END IF;
 SELECT * INTO goal FROM public.goals WHERE id=goal.id;SELECT * INTO hist FROM public.categories WHERE id=hist.id;
 r:=public.manage_goal(27,gen_random_uuid(),jsonb_build_object('action','delete','id',goal.id,'revision',goal.revision,'sourceRevisions',jsonb_build_object('categories:'||hist.id,hist.revision)));
 IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=hist.id AND NOT is_goal AND monthly_amount=50) OR NOT EXISTS(SELECT 1 FROM public.category_monthly_funding WHERE category_id=hist.id) THEN RAISE EXCEPTION 'Goal delete lost envelope/history'; END IF;
 INSERT INTO public.loans(user_id,account_id,name,balance) VALUES(owner,27,'Rollback debt A',8000) RETURNING * INTO loan1;
 INSERT INTO public.loans(user_id,account_id,name,balance) VALUES(owner,27,'Rollback debt B',3000) RETURNING * INTO loan2;
 INSERT INTO public.goals(user_id,account_id,name,target_amount,monthly_contribution,goal_type,purpose,linked_loan_id,funding_category_id) VALUES(owner,27,'Rollback debt goal',8000,200,'debt-paydown','debt',loan1.id,b.id) RETURNING * INTO goal;
 cmd:=jsonb_build_object('action','relink','id',goal.id,'revision',goal.revision,'source',jsonb_build_object('table','loans','id',loan2.id),'sourceRevisions',jsonb_build_object('loans:'||loan1.id,loan1.revision,'loans:'||loan2.id,loan2.revision));
 rev:=loan2.revision;UPDATE public.loans SET balance=2900 WHERE id=loan2.id RETURNING * INTO loan2;
 IF public.manage_goal(27,gen_random_uuid(),cmd)->>'status'<>'conflict' THEN RAISE EXCEPTION 'Stale source balance accepted'; END IF;
 cmd:=jsonb_set(cmd,ARRAY['sourceRevisions','loans:'||loan2.id],to_jsonb(loan2.revision));
 r:=public.manage_goal(27,gen_random_uuid(),cmd);
 IF NOT EXISTS(SELECT 1 FROM public.goals WHERE id=goal.id AND target_amount=2900 AND linked_loan_id=loan2.id AND funding_category_id=b.id AND monthly_contribution=200) THEN RAISE EXCEPTION 'Debt relink failed'; END IF;
 SELECT * INTO b FROM public.categories WHERE id=b.id;
 BEGIN
  PERFORM public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','archive','records',jsonb_build_array(jsonb_build_object('id',b.id,'revision',b.revision))));
  RAISE EXCEPTION 'Goal payment envelope archived';
 EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 INSERT INTO public.non_cash_assets(account_id,name,asset_type,current_value) VALUES(27,'Rollback investment A','investment',1000) RETURNING * INTO asset1;
 INSERT INTO public.non_cash_assets(account_id,name,asset_type,current_value) VALUES(27,'Rollback investment B','investment',2000) RETURNING * INTO asset2;
 INSERT INTO public.goals(user_id,account_id,name,target_amount,goal_type,purpose,linked_non_cash_asset_id) VALUES(owner,27,'Rollback retirement',400000,'asset-linked','retirement',asset1.id) RETURNING * INTO goal;
 r:=public.manage_goal(27,gen_random_uuid(),jsonb_build_object('action','relink','id',goal.id,'revision',goal.revision,'source',jsonb_build_object('table','non_cash_assets','id',asset2.id),'sourceRevisions',jsonb_build_object('non_cash_assets:'||asset1.id,asset1.revision,'non_cash_assets:'||asset2.id,asset2.revision)));
 IF NOT EXISTS(SELECT 1 FROM public.goals WHERE id=goal.id AND linked_non_cash_asset_id=asset2.id AND target_amount=400000) THEN RAISE EXCEPTION 'Investment relink failed'; END IF;
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.envelope_housekeeping(27); RAISE EXCEPTION 'Unauthorized read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.manage_goal(27,gen_random_uuid(),cmd); RAISE EXCEPTION 'Unauthorized goal edit'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.manage_envelopes(27,gen_random_uuid(),jsonb_build_object('action','order','records',all_records)); RAISE EXCEPTION 'Unauthorized envelope edit'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 IF has_function_privilege('authenticated','public.category_housekeeping_usage(bigint)','EXECUTE') THEN RAISE EXCEPTION 'Usage helper exposed'; END IF;
 RAISE NOTICE 'PASS goal unlink/delete, account exclusion, balance preservation, envelope plan/history preservation, debt baseline, investment tracking, source conflicts, access';
END $$;

DO $$ DECLARE owner uuid; card public.credit_cards; loan public.loans; goal public.goals; r jsonb; before_money numeric;
BEGIN
SELECT owner_id INTO owner FROM public.budget_accounts WHERE id=27;
PERFORM set_config('request.jwt.claim.sub',owner::text,true);
INSERT INTO public.loans(user_id,account_id,name,balance) VALUES(owner,27,'Rollback card old loan',5000) RETURNING * INTO loan;
INSERT INTO public.credit_cards(user_id,account_id,name,credit_limit,available_credit,current_balance,statement_balance,carried_debt_balance,carried_debt_as_of) VALUES(owner,27,'Rollback card new source',10000,7000,3000,2000,500,current_date) RETURNING * INTO card;
INSERT INTO public.goals(user_id,account_id,name,target_amount,goal_type,purpose,linked_loan_id) VALUES(owner,27,'Rollback debt relink card',5000,'debt-paydown','debt',loan.id) RETURNING * INTO goal;
SELECT public.budget_available_money(27) INTO before_money;
r:=public.manage_goal(27,gen_random_uuid(),jsonb_build_object('action','relink','id',goal.id,'revision',goal.revision,'source',jsonb_build_object('table','credit_cards','id',card.id),'sourceRevisions',jsonb_build_object('loans:'||loan.id,loan.revision,'credit_cards:'||card.id,card.revision)));
IF NOT EXISTS(SELECT 1 FROM public.goals WHERE id=goal.id AND linked_loan_id IS NULL AND linked_credit_card_id=card.id AND target_amount=3000) OR public.budget_available_money(27)<>before_money THEN RAISE EXCEPTION 'Card source used wrong debt basis or changed available money'; END IF;
RAISE NOTICE 'PASS card tracking uses full current liability, without changing carried or statement balances';
END $$;
